import{_ as t,o as e,c as o,ag as c}from"./chunks/framework.OvD5kfkl.js";const _=JSON.parse('{"title":"键位总览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keys.md","filePath":"guide/keys.md","lastUpdated":1792170211000}'),a={name:"guide/keys.md"};function r(i,d,h,n,l,s){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="键位总览" tabindex="-1">键位总览 <a class="header-anchor" href="#键位总览" aria-label="Permalink to &quot;键位总览&quot;">​</a></h1><p>默认键位。<code>WASD</code> / <code>HJKL</code> 与两个功能键可以在<a href="/guide/settings.html">应用设置</a>里调整，其余按键在 v0.1 中写死。</p><table tabindex="0"><thead><tr><th>键</th><th>生效场景</th><th>行为</th></tr></thead><tbody><tr><td><code>F</code></td><td>任意 App，非 hint 模式</td><td>进入 hint 模式，屏幕上出现标签</td></tr><tr><td><code>F</code></td><td>hint 模式内</td><td>退出 hint 模式，不产生点击</td></tr><tr><td><code>a</code>–<code>z</code></td><td>hint 模式内</td><td>依次写入输入缓冲，凑成完整标签即触发点击</td></tr><tr><td><code>Backspace</code></td><td>hint 模式内</td><td>删掉缓冲里最后一个字符</td></tr><tr><td><code>Esc</code> / <code>Q</code></td><td>hint 模式内</td><td>退出 hint 模式，不产生点击</td></tr><tr><td><code>W</code> <code>A</code> <code>S</code> <code>D</code></td><td>hint 模式内外均可</td><td>光标向上 / 左 / 下 / 右移动</td></tr><tr><td><code>H</code> <code>J</code> <code>K</code> <code>L</code></td><td>hint 模式内外均可</td><td>同上，Vim 习惯的另一组</td></tr><tr><td><code>Space</code></td><td>hint 模式内且光标已停在某目标上</td><td>点击光标所在元素</td></tr><tr><td>光标点击键（默认 <code>Space</code>，可切 <code>Enter</code>）</td><td>hint 模式外且光标存在</td><td>点击光标所在元素</td></tr><tr><td>通知键（默认 <code>Space</code>，可切 <code>Enter</code>）</td><td>hint 模式外且有 heads-up 通知</td><td>点开那条通知</td></tr></tbody></table><h2 id="被保留的字母" tabindex="-1">被保留的字母 <a class="header-anchor" href="#被保留的字母" aria-label="Permalink to &quot;被保留的字母&quot;">​</a></h2><p>标签不会用掉做控制用的字母。以下这些在分配标签时被排除：</p><ul><li><code>f</code> — 触发键，任何时候保留。</li><li><code>q</code> — 退出键，任何时候保留。</li><li><code>w</code> <code>a</code> <code>s</code> <code>d</code> — WASD 方向键开着时保留。</li><li><code>h</code> <code>j</code> <code>k</code> <code>l</code> — HJKL 方向键开着时保留。</li></ul><p>两组方向键都开着的默认状态下，可用字符集剩下 16 个字母：<code>b c e g i m n o p r t u v x y z</code>。关掉其中一组，对应四个字母就还给标签，标签会更短。</p><h2 id="一次输入为什么不会误点" tabindex="-1">一次输入为什么不会误点 <a class="header-anchor" href="#一次输入为什么不会误点" aria-label="Permalink to &quot;一次输入为什么不会误点&quot;">​</a></h2><p>hint 模式下任何按键都被消费掉，这是模态的代价：<code>f</code> 打不出字母，空格不会真的空一格。好处是缓冲不会跟输入法串味。</p><p>输入满一个已存在的标签才动作。缓冲目前的内容如果不再是任何标签的前缀，缓冲立刻清零，等你重新输入。这套规则能保证命中，靠的是标签集合本身的前缀无关性，见 <a href="/guide/hints.html">Hint 标签点击</a>。</p>',10)])])}const u=t(a,[["render",r]]);export{_ as __pageData,u as default};
